def max_sum_subarray(arr, k):
    best = float("-inf")
    n = len(arr)
    for i in range(n - k + 1):
        s = 0
        for j in range(i, i + k):
            s += arr[j]
        if s > best:
            best = s
    return best

reference_solution:
def max_sum_subarray(arr, k):
    window = sum(arr[:k])
    best = window
    for i in range(k, len(arr)):
        window += arr[i] - arr[i - k]
        if window > best:
            best = window
    return best
